const allLabSlides = { 1: m1, 2: m2 };
for (const module of [1, 2]) {
  const keys = new Set(adminSlides[module].map(item => item.key));
  assert.equal(keys.size, adminSlides[module].length, "Admin slide keys must be unique");
  assert.equal(new Set(allLabSlides[module].map(item => item.key)).size, allLabSlides[module].length, "Lab slide keys must be unique");
  for (const item of allLabSlides[module]) assert(keys.has(item.note[3]), `Unknown admin link ${item.note[3]}`);
  for (const meta of labs[module]) assert(allLabSlides[module].some(item => item.lab === meta.n), `Lab ${meta.n} has no steps`);
}

export const labSlides = module => allLabSlides[module];
export const labMeta = module => labs[module];
export const setupSlides = module => adminSlides[module];
export const labIntro = module => module === 1
  ? { title: "Module 1 labs", lead: "Six short labs, each placed right after the lesson it practices. Every step tells you what to click or paste and what you should see.", need: ["A browser and a place to take notes", "An email inbox you can open right now (the access form sends your login there)", "No admin access is needed"] }
  : { title: "Module 2 labs", lead: "Four labs, each placed right after its lesson: sign in, draft, send, and check what really happened.", need: ["Your tested lab account", "The agent link from the instructor (not a slide link)", "One approved internal recipient", "Only fictional training data"] };
export { card, flow, grid, fig, terminal, list, rich as richText };
